`filt` raises on code that does not parse, so I'll parse the raw code first and call the filter only when that succeeds. The hypotheses and the decision rule are unchanged.

```python
# Hypothesis (unchanged): extra no_code = EOS in thinking after a code block; extra SE = ordinary slips, not token corruption.
def se_info(code):
    try:
        ast.parse(code or '')
    except SyntaxError as e:
        return False, f'{e.msg} L{e.lineno}: ' + ((e.text or '').strip()[:70])
    try:
        ast.parse(filt(code)); return True, 'raw+filtered ok'
    except Exception as e:
        return True, 'FILTERED-broken ' + type(e).__name__
for k in (13, 14):
    for lbl in ('start','edited'):
        G = load_gen(f'/work/gen_{k}_{lbl}.jsonl')
        nc = [r for r in G if r['status']=='no_code']; se = [r for r in G if r['status']=='syntax_error']
        ncs = []
        for r in nc:
            t = r['text']; ht = '</think>' in t
            tail = t.rstrip()[-12:]
            ncs.append(('T' if ht else 'noT') + '/' + r['finish_reason'][:4] + ('/endfence' if tail.endswith('`'*3) else ''))
        print(f'pass{k} {lbl}: no_code {len(nc)} {dict(collections.Counter(ncs))}')
        for r in se:
            ok, msg = se_info(r['code'])
            print(f'   SE {r["id"]} s{r["sample"]} ntok {r["n_tokens"]} fin {r["finish_reason"][:4]} | {msg}'.encode('ascii','replace').decode()[:190])
